func (r AnalyzeReturn) ConvertToResult(analyzerType, filePath string) *AnalysisResult {
	result := new(AnalysisResult)
	if r.OS != (types.OS{}) {
		result.OS = &r.OS
	}

	if len(r.Packages) > 0 {
		result.PackageInfos = []types.PackageInfo{{
