		return nil
	}

	// library scan for servers need lockfiles
	if len(l.ServerInfo.Lockfiles) == 0 && !l.ServerInfo.FindLock {
		return nil
	}

	seen := map[string]bool{}

	detectFiles := l.ServerInfo.Lockfiles

	// auto detect lockfile
	if l.ServerInfo.FindLock {
		findopt := ""
		for filename := range models.LibraryMap {
			findopt += fmt.Sprintf("-name %q -o ", "*"+filename)
		}

		// delete last "-o "
		// find / -name "*package-lock.json" -o -name "*yarn.lock" ... 2>&1 | grep -v "Permission denied"
		cmd := fmt.Sprintf(`find / ` + findopt[:len(findopt)-3] + ` 2>&1 | grep -v "Permission denied"`)
		r := exec(l.ServerInfo, cmd, noSudo)
		if r.ExitStatus != 0 && r.ExitStatus != 1 {
			return xerrors.Errorf("Failed to find lock files")
		}
		detectFiles = append(detectFiles, strings.Split(r.Stdout, "\n")...)
	}

	for _, path := range detectFiles {
		if path == "" {
			continue
		}
		// skip already exist
		if seen[path] {
			continue
		}
		seen[path] = true
		cmd := fmt.Sprintf("cat %s", path)
		r := exec(l.ServerInfo, cmd, noSudo)
		if !r.isSuccess() {
			return xerrors.Errorf("Failed to get target file: %s, filepath: %s", r, path)
		}
		content := []byte(r.Stdout)
		result, err := analyzer.AnalyzeFile(path, &DummyFileInfo{}, func() ([]byte, error) {
			return content, nil
		})
		if err != nil {
			return xerrors.Errorf("failed to analyze lockfile %s: %w", path, err)
		}
		l.LibraryScanners = append(l.LibraryScanners, convertLibWithScanner(result)...)
	}
	return nil
}

func (l *base) scanWordPress() (err error) {
	wpOpts := []string{l.ServerInfo.WordPress.OSUser,
		l.ServerInfo.WordPress.DocRoot,
		l.ServerInfo.WordPress.CmdPath,
		l.ServerInfo.WordPress.WPVulnDBToken,
	}
	var isScanWp, hasEmptyOpt bool
	}

	if err := db2.Init(config.Conf.TrivyCacheDBDir); err != nil {
		return 0, err
	}
	defer db2.Close()

	for _, lib := range r.LibraryScanners {
		vinfos, err := lib.Scan()
		if err != nil {
			return 0, err
		}
		for _, vinfo := range vinfos {
			mergeLibraryVuln(r, vinfo)
		}
		totalCnt += len(vinfos)
	}

	return totalCnt, nil
}

func mergeLibraryVuln(r *models.ScanResult, vinfo models.VulnInfo) {
	if existing, ok := r.ScannedCves[vinfo.CveID]; ok {
		existing.LibraryFixedIns = append(existing.LibraryFixedIns, vinfo.LibraryFixedIns...)
		existing.Confidences.AppendIfMissing(models.TrivyMatch)
		r.ScannedCves[vinfo.CveID] = existing
		return
	}
	vinfo.Confidences.AppendIfMissing(models.TrivyMatch)
	r.ScannedCves[vinfo.CveID] = vinfo
}

